#!/bin/bash
set -e
echo "Deploying GTM Intel v7 — Structured Pipeline + BuiltWith..."
mkdir -p src/lib
echo  | base64 -d > src/lib/data-layer.ts
echo "✓ src/lib/data-layer.ts"
mkdir -p src/lib
echo  | base64 -d > src/lib/research-engine.ts
echo "✓ src/lib/research-engine.ts"
mkdir -p src/app/api/discover
echo  | base64 -d > src/app/api/discover/route.ts
echo "✓ src/app/api/discover/route.ts"
mkdir -p src/app/api/research
echo  | base64 -d > src/app/api/research/route.ts
echo "✓ src/app/api/research/route.ts"
mkdir -p src/app/setup
echo  | base64 -d > src/app/setup/page.tsx
echo "✓ src/app/setup/page.tsx"
mkdir -p src/app/dashboard
echo  | base64 -d > src/app/dashboard/page.tsx
echo "✓ src/app/dashboard/page.tsx"
git add -A
git commit -m "feat v7: data layer, BuiltWith tech stack, job signal parser, 5-prompt AI pipeline"
git push origin main
vercel --prod
echo "✅ GTM Intel v7 deployed!"